set -eu
cd "$HOME/android-agent"
export PATH="$HOME/.local/share/android-agent-tools/node/bin:$HOME/android-agent/.venv/bin:/usr/bin:/bin:$PATH"
mkdir -p ops/backups/dashboard-improvements-v3
cd frontend
npm run type-check > ../ops/backups/dashboard-improvements-v3/typecheck-before.log 2>&1 || true
cd ..
.venv/bin/python - <<'PY'
from pathlib import Path
import base64,shutil
files={'frontend/src/views/DeviceWorkspaceView.vue': '', 'frontend/src/components/StreamOverview.vue': '', 'frontend/src/composables/deviceLayout.ts': '', 'ops/test_device_layout.mjs': '', 'frontend/src/composables/useH264Stream.ts': '', 'frontend/src/views/DeviceWindowView.vue': '', 'frontend/src/views/PhoneAdminView.vue': ''}
backup=Path('ops/backups/dashboard-improvements-v3')
for rel,value in files.items():
 p=Path(rel);b=backup/rel.replace('/','__')
 if p.exists() and not b.exists():shutil.copy2(p,b)
 p.write_bytes(base64.b64decode(value));print('UPDATED='+rel)
PY
node ops/test_device_layout.mjs
cd frontend
npm run type-check > ../ops/backups/dashboard-improvements-v3/typecheck-after.log 2>&1 || true
cd ..
.venv/bin/python - <<'PY'
from pathlib import Path
import re
folder=Path('ops/backups/dashboard-improvements-v3')
before=(folder/'typecheck-before.log').read_text();after=(folder/'typecheck-after.log').read_text()
def errors(s):return {re.sub(r'\(\d+,\d+\)','(LINE)',line) for line in s.splitlines() if 'error TS' in line}
new=errors(after)-errors(before)
print('EXISTING_TYPECHECK_ERRORS='+str(len(errors(before))))
print('NEW_TYPECHECK_ERRORS='+str(len(new)))
if new:
 print('\n'.join(sorted(new)))
 raise SystemExit('New TypeScript errors; production assets remain untouched')
PY
cd frontend
npm run build-only -- --outDir dist-next
cd ..
.venv/bin/python - <<'PY'
from pathlib import Path
import shutil,time
live=Path('frontend/dist');new=Path('frontend/dist-next');backup=Path('ops/backups/dashboard-improvements-v3/dist-before')
assert (new/'index.html').exists()
if not backup.exists():shutil.copytree(live,backup)
# Copy hashed assets first; replace index last so active viewers remain valid.
for p in new.rglob('*'):
 if p.is_file() and p.name!='index.html':
  dest=live/p.relative_to(new);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
tmp=live/'index.html.next';shutil.copy2(new/'index.html',tmp);tmp.replace(live/'index.html')
print('ATOMIC_FRONTEND_UPDATE=READY; no service restart needed')
PY
